for fixture in FIXTURES:
 problem=definition(**copy.deepcopy(fixture))
 before=copy.deepcopy(problem)
 # Independent full enumeration contains no frontier compaction.
 best=max((objective(state),state['remaining'])
          for schedule in itertools.product(range(len(problem['choices'])),repeat=problem['days'])
          for state in [replay(problem,list(schedule))])
 report=solve(problem)
 assert (report['score'],report['remaining'])==best, (report['score'],best,report['schedule'])
 assert problem==before
 with tempfile.TemporaryDirectory() as tmp:
  path=Path(tmp)/'design.json'
  save_design(path,report)
  restored=load_design(path)
  assert restored['world']==replay(problem,report['schedule'])['world']
